<script setup lang="ts">
import {confirmAction} from '../composables/confirmation';
import {onMounted,ref} from 'vue';import {apiGet,apiPost,ApiError,uploadExcel,downloadTemplate} from '../api/client';import {saveFile} from '../platform/saveFile';
const emit=defineEmits<{expired:[]}>();const tab=ref('overview'),overview=ref<Record<string,number>>({}),points=ref<any[]>([]),questions=ref<any[]>([]),query=ref(''),page=ref(1),total=ref(0),busy=ref(false),error=ref(''),notice=ref('');
const questionId=ref(''),versions=ref<any[]>([]),selectedVersion=ref(1),reason=ref('');
const q=ref({pointId:'',stem:'',standardAnswer:'',explanation:''});const pointKey=ref(''),point=ref({name:'',grade:1,semester:'上册',textbook:'',evidence:'',enabled:false});
const importFile=ref<File|null>(null),importReport=ref<any>(null);
async function run(f:()=>Promise<void>){if(busy.value)return;busy.value=true;error.value='';try{await f();}catch(e){error.value=e instanceof Error?e.message:'操作失败';if(e instanceof ApiError&&e.status===401)emit('expired');}finally{busy.value=false;}}
async function load(){const [stats,categories,list]=await Promise.all([apiGet<Record<string,number>>('/admin/overview'),apiGet<any[]>('/admin/points'),apiGet<any>(`/admin/questions?query=${encodeURIComponent(query.value)}&page=${page.value}`)]);overview.value=stats;points.value=categories;questions.value=list.items;total.value=list.total;if(!q.value.pointId)q.value.pointId=categories[0]?.id??'';}
const refresh=()=>run(load);
function newQuestion(){questionId.value='';q.value={pointId:points.value[0]?.id??'',stem:'',standardAnswer:'',explanation:''};versions.value=[];notice.value='新题保存后为待核对状态。';}
const edit=(row:any)=>run(async()=>{questionId.value=row.id;q.value={pointId:row.pointId,stem:row.stem,standardAnswer:row.standardAnswer,explanation:row.explanation};versions.value=await apiGet<any[]>(`/admin/questions/${row.id}/versions`);selectedVersion.value=row.revision;reason.value='';});
const save=()=>run(async()=>{const row=await apiPost<any>(questionId.value?`/admin/questions/${questionId.value}`:'/admin/questions',q.value,questionId.value?'PUT':'POST');questionId.value=row.id;notice.value='已保存，需重新核对后启用。';versions.value=await apiGet<any[]>(`/admin/questions/${row.id}/versions`);selectedVersion.value=row.revision;await load();});
const review=(row:any)=>run(async()=>{if(!await confirmAction(`请确认已核对这道题的分类、答案和解析：\n${row.stem}\n标准答案：${row.standardAnswer}\n${row.explanation}`))return;await apiPost(`/admin/questions/${row.id}/review`,{confirm:true,expectedRevision:row.revision});notice.value='该版本已标记核对通过。';await load();});
const enable=(row:any)=>run(async()=>{if(row.enabled&&!await confirmAction('普通停用仅影响新组卷，已有题目快照和结果保留。确认停用？'))return;await apiPost(`/admin/questions/${row.id}/enabled`,{enabled:!row.enabled});await load();});
const markError=()=>run(async()=>{if(!questionId.value||!reason.value.trim())throw new Error('请选择版本并填写数学错误原因');const impact=await apiGet<any>(`/admin/questions/${questionId.value}/versions/${selectedVersion.value}/impact`);if(!await confirmAction(`确认第${selectedVersion.value}版存在数学错误？\n${impact.unfinished}份未完成练习将作废，${impact.completed}份成绩保留并标记。\n原因：${reason.value}`))return;const result=await apiPost<any>(`/admin/questions/${questionId.value}/versions/${selectedVersion.value}/error`,{confirm:true,reason:reason.value});notice.value=`已处理，涉及${result.affectedPractices}份练习。`;await load();versions.value=await apiGet<any[]>(`/admin/questions/${questionId.value}/versions`);});
function editPoint(row?:any){pointKey.value=row?.id??'';point.value=row?{name:row.name,grade:row.grade,semester:['上册','下册'].includes(row.semester)?row.semester:'上册',textbook:row.textbook,evidence:row.evidence,enabled:row.enabled}:{name:'',grade:1,semester:'上册',textbook:'',evidence:'',enabled:false};}
const savePoint=()=>run(async()=>{await apiPost(pointKey.value?`/admin/points/${pointKey.value}`:'/admin/points',point.value,pointKey.value?'PUT':'POST');notice.value='知识点已保存，历史归属和题目快照保留。';await load();});
const search=()=>{page.value=1;void refresh();};const next=(step:number)=>{page.value+=step;void refresh();};
const template=()=>run(async()=>{await saveFile(await downloadTemplate(),'mathdrill-template.xlsx');});
const upload=()=>run(async()=>{if(!importFile.value)throw new Error('请先选择.xlsx文件');if(importFile.value.size>5*1024*1024)throw new Error('文件不能超过5MB');importReport.value=await uploadExcel(importFile.value);});
const importConfirm=()=>run(async()=>{if(!importReport.value||!await confirmAction('确认整批导入这些校验通过的题目？导入后仍需内容核对。'))return;importReport.value=await apiPost(`/admin/imports/${importReport.value.id}/confirm`,{confirm:true});await load();});
const importStatus=()=>run(async()=>{if(importReport.value)importReport.value=await apiGet(`/admin/imports/${importReport.value.id}`);});
onMounted(refresh);
</script>
<template><section><p class="eyebrow">内容质量与日常维护</p><h1>管理员后台</h1><p v-if="error" class="error" role="alert">{{error}}</p><p v-if="notice" class="notice" role="status">{{notice}}</p><div class="quick"><button @click="tab='overview'">管理概览</button><button @click="tab='questions'">题库维护</button><button @click="tab='points'">知识点</button><button @click="tab='import'">Excel导入</button></div><button :disabled="busy" @click="refresh">刷新管理数据</button>
<div v-if="tab==='overview'" class="card"><h2>基础统计</h2><p>题目总数：{{overview.questionTotal}}</p><p>可用题数：{{overview.available}}</p><p>学生账号数：{{overview.students}}</p><p>已完成练习数：{{overview.completed}}</p><p class="muted">成绩由正式提交生成，后台不提供改分。</p></div>
<section v-else-if="tab==='import'"><h2>整批导入题目</h2><button class="secondary" :disabled="busy" @click="template">下载或分享Excel模板</button><p class="muted">仅.xlsx，一批最多500行、5MB。学期填上册/下册，当前答案类型填整数，标准答案不使用公式。</p><label for="importFile">选择Excel文件</label><input id="importFile" type="file" accept=".xlsx" @change="importFile=($event.target as HTMLInputElement).files?.[0]??null;importReport=null"><button class="primary" :disabled="busy||!importFile" @click="upload">上传并检查整批</button><div class="card" v-if="importReport"><h2>{{importReport.state==='READY'?'校验通过，等待确认':importReport.state==='IMPORTED'?'已导入':'整批未导入'}}</h2><p>总数{{importReport.total}} · 成功{{importReport.success}} · 未导入{{importReport.notImported}}</p><ul v-if="importReport.issues?.length"><li v-for="(issue,index) in importReport.issues" :key="index">第{{issue.row}}行 · {{issue.column}}：{{issue.reason}}</li></ul><p v-if="importReport.blockedRows?.length" class="muted">因整批拒绝而未导入的其他行：{{importReport.blockedRows.join('、')}}</p><button v-if="importReport.state==='READY'" class="primary" :disabled="busy" @click="importConfirm">确认导入整批</button><button class="secondary" :disabled="busy" @click="importStatus">查询本批结果</button><p class="muted">导入成功后为待核对状态，需核对通过再启用。</p></div></section>
<template v-else-if="tab==='questions'"><form @submit.prevent="search"><label for="questionSearch">题干查询</label><input id="questionSearch" v-model="query"><button class="secondary" :disabled="busy">查询题目</button></form><button class="primary" @click="newQuestion">新增题目</button><form class="card" @submit.prevent="save"><h2>{{questionId?'编辑题目':'录入新题'}}</h2><label for="questionPoint">知识点</label><select id="questionPoint" v-model="q.pointId" required><option v-for="p in points" :key="p.id" :value="p.id">{{p.grade}}年级 · {{p.name}}</option></select><label for="questionStem">题干</label><input id="questionStem" v-model="q.stem" maxlength="200" required><label for="questionStandard">标准答案（非负整数）</label><input id="questionStandard" v-model="q.standardAnswer" pattern="[0-9]+" maxlength="128" required><label for="questionExplanation">解析</label><textarea id="questionExplanation" v-model="q.explanation" maxlength="500" required></textarea><button class="primary" :disabled="busy">保存为待核对</button></form>
<details v-if="questionId"><summary>历史版本与数学错误处置</summary><p class="muted">普通停用无需使用此操作；请核对真正有误的历史版本。</p><select v-model.number="selectedVersion"><option v-for="v in versions" :key="v.revision" :value="v.revision">第{{v.revision}}版：{{v.stem}} / {{v.standardAnswer}}{{v.isError?'（已确认错误）':''}}</option></select><label for="mathErrorReason">错误原因</label><textarea id="mathErrorReason" v-model="reason" maxlength="500"></textarea><button class="secondary" :disabled="busy" @click="markError">查看影响并确认数学错误</button></details>
<div v-for="row in questions" :key="row.id" class="card"><h2>{{row.stem}}</h2><p>标准答案：{{row.standardAnswer}} · 第{{row.revision}}版</p><p class="muted">{{row.grade}}年级 · {{row.pointName}} · {{row.reviewed?'已核对':'待核对'}} · {{row.enabled?'启用':'停用'}}<br>{{row.explanation}}</p><div class="quick"><button :disabled="busy" @click="edit(row)">编辑</button><button :disabled="busy||row.reviewed" @click="review(row)">核对通过</button><button :disabled="busy||(!row.reviewed&&!row.enabled)" @click="enable(row)">{{row.enabled?'普通停用':'启用'}}</button></div></div><div class="pager"><button :disabled="busy||page<=1" @click="next(-1)">上一页</button><span>{{page}} / {{Math.max(1,Math.ceil(total/30))}}</span><button :disabled="busy||page*30>=total" @click="next(1)">下一页</button></div></template>
<template v-else-if="tab==='points'"><button class="primary" @click="editPoint()">新增知识点</button><form class="card" @submit.prevent="savePoint"><label for="pointName">知识点名称</label><input id="pointName" v-model="point.name" maxlength="100" required><label for="pointGrade">年级</label><select id="pointGrade" v-model.number="point.grade"><option v-for="n in [1,2,3]" :key="n" :value="n">{{n}}年级</option></select><label for="pointSemester">学期</label><select id="pointSemester" v-model="point.semester"><option>上册</option><option>下册</option></select><label for="textbook">教材名称及版次</label><input id="textbook" v-model="point.textbook" maxlength="256" required><label for="pointEvidence">目录或页码依据</label><textarea id="pointEvidence" v-model="point.evidence" maxlength="1000" required></textarea><label><input class="checkbox" v-model="point.enabled" type="checkbox">启用该分类供新组卷使用</label><button class="primary" :disabled="busy">保存知识点</button></form><div v-for="p in points" :key="p.id" class="card"><h2>{{p.grade}}年级 · {{p.name}}</h2><p>{{p.semester}} · {{p.enabled?'启用':'停用'}}</p><p class="muted">{{p.textbook}}<br>{{p.evidence}}</p><button @click="editPoint(p)">编辑分类</button></div></template></section></template>
